/* ---- MAN: editing (main loop, the SLICES page; based on hugelton/Felucca#27 by andreahaku). Begin with
 * slc_man_begin, change the copy it returns with move / split / join, then slc_man_commit puts it in use. */
/* the decoder state before sample pos: decoded from the grid point at or below it */
static uint32_t slc_state_at(const slc_src_t *s, uint32_t pos)
{
    slc_dec_t d;
    uint32_t k = (pos << SLC_GRID_LOG2) / s->len;            /* (pos < 2^18: a slot holds < 200 K samples) */
    k = k < SLC_GRID ? k : SLC_GRID - 1u;
    while (k && slc_gpos(s, k) > pos)
        k--;
    while (k + 1u < SLC_GRID && slc_gpos(s, k + 1u) <= pos)
        k++;
    slc_dec_at(&d, slc_gpos(s, k), s->grid[k]);
    while (d.pos < pos)
        slc_dec_next(s, &d);
    return slc_dec_st(&d);
}

/* every track's engine one this firmware has (DIGITAL, 1, is one: it converts; (2.0) only with FELUCCA_LEGACY): a
 * project of another number is not one (it never was: no engine number past the last was ever stored) */
static int proj_engines_ok(const project_t *q)
{
    uint32_t t;
    for (t = 0; t < NTRK; t++)
        if (q->t[t].engine >= NENGINES || (!FELUCCA_LEGACY && !FELUCCA_FM4 && q->t[t].engine == ENGI_DIGITAL))
            return 0;
    return 1;
}

static void panel_init(void)                     /* also after a flash load: ids are used as array indexes and shifts */
{
    uint32_t i, buttons = 0, encoders = 0, ok = panel.magic == PANEL_MAGIC;
    for (i = 0; ok && i < NB; i++) {
        ok = panel.btn[i] < PANEL_NBTN && !(buttons & (1u << panel.btn[i]));
        if (ok) buttons |= 1u << panel.btn[i];
    }
    for (i = 0; ok && i < NE; i++) {
        ok = panel.enc[i] < PANEL_NENC && !(encoders & (1u << panel.enc[i])) &&
             (panel.dir[i] == 1 || panel.dir[i] == -1);
        if (ok) encoders |= 1u << panel.enc[i];
    }
    if (!ok)
        panel = PANEL_DEFAULT;
}

/* icon id at size 12, 16 or 24 px (24: the header battery and USB, the FX map; one missing: its 12 px cell),
 * fg on bg; returns its width */
static int32_t cv_icon_on(int32_t x, int32_t y, uint32_t size, uint32_t id, uint16_t fg, uint16_t bg)
{
    int32_t k;
    if (id - ICON_TRK < NTRK)
        return cv_trk(x, y, size, id - ICON_TRK, fg, bg);
    if ((k = icon_cell(&size, id)) < 0)
        return 0;
    cv_alpha_hc(x, y, size, size, size == 24u ? AI24_DATA + AI24_OFF[k] : size == 16u ? AI16_DATA + AI16_OFF[k] :
                AI12_DATA + AI12_OFF[k], AI_HC, ramp(fg, bg));
    GFX_HOOK_ICON(x, y, size, id);
    if (GFX_HOOKS && icon_lint_ink) {                /* ((Skiff phase 6) a cell with no room for its empty margins) */
        int32_t b[4];
        icon_ink(size, id, b);
        GFX_HOOK_TEXT(x + b[0], y + b[1] + cv_oy, x + b[2], y + b[3] + cv_oy, "icon", 4u);
    } else {
        GFX_HOOK_TEXT(x, y + cv_oy, x + (int32_t)size, y + cv_oy + (int32_t)size, "icon", 4u);
    }
    return (int32_t)size;
}

static int fl_write(uint32_t off, const void *p, uint32_t n)
