/* ------------------------------------------------- parameter locks --- */
/* 1.1 (Discussions #75, #53): on SEQ > NOTES, hold a step and turn KNOB 1..4: the step gets a lock of the parameter
 * that knob edits on the sound page shown last (ui.plk_src: HOME's four, ENV, LFO, FX, EDIT 1 / 2, OP ENV, ..; the
 * cards show those four while a step is held, a locked value bright, the sound's own DIM). The step held: on the
 * DRUM grid its white keys (several at once: each gets the lock; a press on a hit takes it away only when let go,
 * and not at all when it was held for a lock), on the roll the step being entered (its note keys held). [EDIT]
 * tapped meanwhile clears the held steps' locks (EDIT alone still clears the step, its locks with it). Not while a
 * song plays (STOP TO EDIT). A lock is a motion record (motion.c): AUTOMATION's PLAY plays it, CLEAR clears it */
static uint64_t lock_held(void)
{
    const track_t *t = TSEL;
    uint32_t k, len = (uint32_t)t->p[P_SLEN], keys = fm1_in.notes & ~kb_layer;
    uint64_t m = 0;
    if (ui.home || ui.menu || ui.confirm || ui.layer || name_on() || !song.seq_mode || !step_page(cur_page()->graph) ||
        !keys)
        return 0;
    if (!grid_on())                                     /* the roll: the step being entered */
        return ui.entry_open && !live_rec_sel() && ui.cursor < len ? (uint64_t)1 << ui.cursor : 0u;
    for (k = 0; k < 27u; k++)
        if (((keys >> k) & 1u) && !key_black(k) && ui.bank * 16u + key_place(k) < len)
            m |= (uint64_t)1 << (ui.bank * 16u + key_place(k));
    return m;
}

static void led_put(uint8_t *nl, uint32_t id, int on)
{
    uint8_t q = led_pos[id];
    if (q != 0xFF && on)
        nl[q >> 3] |= (uint8_t)(1u << (q & 7u));
}

static void menu_tabs(void)                            /* (in screen rows: cv_oy set by the caller) */
{
    int32_t a[MTAB_COUNT], x[MTAB_COUNT], w[MTAB_COUNT];
    uint32_t k;
    mt_layout(a, x, w);
    for (k = 0; k < MTAB_COUNT; k++) {
        int on = k == (uint32_t)((mt.pos + MT_ONE / 2) / MT_ONE);   /* (half way, the shown look moves over) */
        uint16_t bg = on ? T_ACCENT : T_SURF;
        if (on && ux.neon) {                           /* ((Skiff N3) NEON: lit pink into violet) */
            uint16_t st[2] = {T_THEME, NE_VIOLET};
            ne_hgrad(x[k], MT_Y, w[k], MT_H, st, 2);
        } else if (ux.quark) {                         /* ((Skiff Q2) QUARK: lit cyan; the others in corners) */
            cv_rect(x[k], MT_Y, w[k], MT_H, on ? T_THEME : T_BG);
            if (!on)
                qk_corners(x[k], MT_Y, w[k], MT_H, T_DIM, 3);
        } else
        cv_rrect(x[k], MT_Y, w[k], MT_H, ux.crypt ? 0 : -8, bg, T_BG);   /* ((Skiff) CRYPT: square) */
        GFX_HOOK_ALIGN(x[k], MT_Y, x[k] + MT_IW, MT_Y + MT_H, AL_HV, "menu tab icon centred in its cushion");
        if (ux.quark)
            bg = on ? T_THEME : T_BG;
        cv_icon_in(x[k], MT_Y, MT_IW, MT_H, 16, MTAB_ICON[k], on ? T_INK : T_MID, bg);
        if (a[k] == MT_ONE) {                          /* (settled: its name) */
            GFX_HOOK_ALIGN(0, MT_Y, 0, MT_Y + MT_H, AL_V, "menu tab name centred up/down");
            cv_text_on(x[k] + MT_NX, MT_Y + (menu_large() ? CAP_IN(M, MT_H) : CAP_IN(S, MT_H)), mt_font(), MTAB_NAME[k],
                       T_INK, bg);
        }
    }
}

static void card_mot_of(const int16_t *vp)
{
    uintptr_t id = ((uintptr_t)vp - (uintptr_t)TSEL->p) / sizeof *vp;   /* (not the track's: huge) */
    card_mot_next = (uint8_t)(id < P_COUNT && ((card_mot_mask[id / 32u] >> (id % 32u)) & 1u));
}

/* the bar track k shows: the one its sequencer is in (from its first step), and how many of its cells exist */
static uint32_t hl_bar(const track_t *t, uint32_t *n)
{
    uint32_t len = t->p[P_SLEN] > 0 ? (uint32_t)t->p[P_SLEN] : 16u, first = (t->seq_idx % len) / 16u * 16u;
    *n = len - first > 16u ? 16u : len - first;
    return first;
}

/* a character of the theme's face (CRYPT's pixel S or V) on a baseline */
static void cr_ch(int32_t x, int32_t base, const aafont_t *f, char ch, uint16_t c)
{
    char s[2] = {ch, 0};
    cv_text(x, base - f->asc, f, s, c);
}

/* a lit tube over a box: its glow 1 px round it (into `under`) and its hot top; drawn after: ne_tube_top */
static void ne_tube(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c, uint16_t under)
{
    cv_rect(x - 1, y - 1, w + 2, h + 2, ux_mix(c, under, 62));
    cv_rect(x, y, w, h, c);
    if (w > 2 && h > 3)
        cv_rect(x + 1, y + 1, w - 2, 1, ux_mix(c, T_TEXT, 55));
}

static inline void slc_dec_at(slc_dec_t *d, uint32_t pos, uint32_t st)
{
    d->pos = pos;
    d->pred = (int16_t)(st & 0xFFFFu);
    d->idx = (int32_t)((st >> 16) & 127u);
    d->seg = st >> 24;
}

/* a cell at x, y, h px high: big (h > 30, FX's effects, LF_W wide) the icon alone, 24 px, under the note, a name in
 * the top right corner; over 24 px (SEQ TOOLS) compact, the icon at a side; else a key's row (the EDIT layer): the
 * icon and the name on its middle. ((Skiff phase 6) GLO's and FX's track cells: l6_*) */
/* a cell's box: its fill on the panel ((Skiff) a RAISE, idle, cell is a SURF tile on the ground). Cells are 4 px
 * apart from x 6, y 4. Returns the fill */
static uint16_t lc_box(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t fill)
{
    if (fill == T_RAISE)
        fill = T_SURF;
    cv_rrect(x, y, w, h, ux.crypt ? 0 : 4, fill, cv_bg);
    if (ux.crypt && fill == T_SURF) {                    /* (Skiff C3) CRYPT: an idle cell stone, framed */
        cr_stone(x, y, w, h, fill);
        cv_frame(x, y, w, h, T_LINE);
    }
    return fill;
}

static int32_t gr_find(uint32_t src, uint32_t note)
{
    uint32_t i, nz = gr_nz(src);
    int32_t zl = src < SMP_NSETS ? 0 : -1;
    if (smp_set_missing(src))
        return GR_SINE;
    for (i = 0; i < nz && i < GR_MAXZ; i++) {
        const smp_zone_t *z = gr_zone(src, i);
        if (note >= z->lo && note <= z->hi)
            zl = (int32_t)i;
    }
    return zl;
}

static void phys_note_on(track_t *t, voice_t *v)
{
    phys_slot_t *S = phys_slot_of(t, v);
    uint32_t md = (uint32_t)t->p[P_E0] % PM_COUNT;
    if (!S)
        return;
    if ((!v->env && !v->env_out) || S->model != md)     /* a fresh voice (not a retrigger): from rest */
        phys_reset(S, md, rng());
    switch (md) {
    case PM_MODAL:
    case PM_MEMB:
        S->u.m.trig = 1;                                 /* a retrigger strikes the ringing body again */
        break;
    default:                                             /* STRNG, SYMP */
        S->u.s.trig = 1;
        break;
    }
}

/* hundredths: "14.00", "0.50" */
static void fm_hundredths(char *b, int32_t v)
{
    fmt_int(b, v / 100);
    b += str_len(b);
    *b++ = '.';
    *b++ = (char)('0' + v / 10 % 10);
    *b++ = (char)('0' + v % 10);
    *b = 0;
}

/* what the cards and the panel show besides the track's values (ui_graph.c graph_signature hashes those) */
static uint32_t fm_sig(void)
{
    return (fm6_pgen[fm_tr()] + 1u) * 2246822519u ^ (fm_ui[0] + fm_ui[1] * 7u + fm_ui[2] * 49u) * 40503u ^
           (ui.hot_t ? ui.hot_col + 1u : 0u) * 65537u;
}
